{"draft":{"version":"a0","html":"<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Pop the Bubbles</title>
<style>
  html, body {
    margin: 0;
    padding: 0;
    width: 100%;
    height: 100%;
    background: #fbf7ee;
    overflow: hidden;
    font-family: "Arial Narrow", Arial, sans-serif;
  }
  #wrap {
    position: relative;
    width: 100vw;
    height: 100dvh;
  }
  canvas {
    display: block;
    width: 100%;
    height: 100%;
    touch-action: none;
  }
  #clearBtn {
    position: absolute;
    top: 14px;
    right: 14px;
    min-height: 48px;
    min-width: 100px;
    padding: 8px 18px;
    background: #ff48b0;
    color: #fbf7ee;
    border: 3px solid #5b3a8c;
    border-radius: 10px;
    font-weight: bold;
    font-size: 16px;
    font-family: inherit;
    letter-spacing: 1px;
    cursor: pointer;
    z-index: 10;
    text-transform: uppercase;
  }
  #clearBtn:active {
    transform: translateY(1px);
  }
  #tally {
    position: absolute;
    top: 14px;
    left: 14px;
    color: #0078bf;
    font-weight: bold;
    font-size: 22px;
    letter-spacing: 1px;
    z-index: 10;
    text-shadow: 1px 1px 0 #ff48b0;
  }
</style>
</head>
<body>
<div id="wrap">
  <canvas id="game"></canvas>
  <div id="tally">POPS: 0</div>
  <button id="clearBtn">Clear</button>
</div>
<script>
// ---- Bridge helper (verbatim) ----
const CARTRIDGE = {
  send(type, payload = {}) {
    window.parent.postMessage(
      { source: "cartridge", v: 1, type, payload },
      "*",
    );
  },
};
</script>
<script>
(function () {
  const canvas = document.getElementById("game");
  const ctx = canvas.getContext("2d");
  const clearBtn = document.getElementById("clearBtn");
  const tallyEl = document.getElementById("tally");

  let dpr = Math.max(1, window.devicePixelRatio || 1);
  let W = 0, H = 0;

  function resize() {
    W = window.innerWidth;
    H = window.innerHeight;
    canvas.width = Math.floor(W * dpr);
    canvas.height = Math.floor(H * dpr);
    canvas.style.width = W + "px";
    canvas.style.height = H + "px";
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    if (!grainTile) buildGrain();
  }
  window.addEventListener("resize", resize);

  // ---- Grain tile (pre-rendered noise) ----
  let grainTile = null;
  function buildGrain() {
    const size = 128;
    const gCanvas = document.createElement("canvas");
    gCanvas.width = size;
    gCanvas.height = size;
    const gctx = gCanvas.getContext("2d");
    const imgData = gctx.createImageData(size, size);
    for (let i = 0; i < imgData.data.length; i += 4) {
      const v = Math.random() * 255;
      imgData.data[i] = v;
      imgData.data[i + 1] = v;
      imgData.data[i + 2] = v;
      imgData.data[i + 3] = 255;
    }
    gctx.putImageData(imgData, 0, 0);
    grainTile = gCanvas;
  }

  // ---- Colours ----
  const PAPER = "#fbf7ee";
  const INK1 = "#ff48b0";
  const INK2 = "#0078bf";
  const OVERLAP = "#5b3a8c";

  // ---- State ----
  const pieces = []; // bubbles: {x,y,r,vx,vy,color,popped,popT}
  let tally = 0;
  let paused = false;
  let running = false; // becomes true after first tap
  let hintPulse = 0;

  function rand(a, b) {
    return a + Math.random() * (b - a);
  }

  function spawnBatch(n) {
    for (let i = 0; i < n; i++) {
      spawnOne();
    }
  }

  function spawnOne() {
    const r = rand(24, 48);
    const x = rand(r, W - r);
    const y = rand(r, H - r);
    const color = Math.random() < 0.5 ? INK1 : INK2;
    pieces.push({
      x, y, r,
      vx: rand(-18, 18),
      vy: rand(-14, 14),
      color,
      born: performance.now(),
      popped: false,
      popT: 0,
    });
  }

  function maintainBubbles() {
    // keep a healthy count of live bubbles
    const alive = pieces.filter((p) => !p.popped);
    if (alive.length < 9) {
      spawnOne();
    }
  }

  function settle(list, dt) {
    for (const p of list) {
      if (p.popped) {
        p.popT += dt;
        continue;
      }
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      if (p.x - p.r < 0) { p.x = p.r; p.vx *= -1; }
      if (p.x + p.r > W) { p.x = W - p.r; p.vx *= -1; }
      if (p.y - p.r < 0) { p.y = p.r; p.vy *= -1; }
      if (p.y + p.r > H) { p.y = H - p.r; p.vy *= -1; }
    }
    // remove fully-popped bubbles after their animation
    for (let i = pieces.length - 1; i >= 0; i--) {
      if (pieces[i].popped && pieces[i].popT > 0.28) {
        pieces.splice(i, 1);
      }
    }
    maintainBubbles();
  }

  function popAt(x, y) {
    // find topmost unpopped bubble under point
    for (let i = pieces.length - 1; i >= 0; i--) {
      const p = pieces[i];
      if (p.popped) continue;
      const dx = x - p.x, dy = y - p.y;
      if (dx * dx + dy * dy <= p.r * p.r) {
        p.popped = true;
        p.popT = 0;
        tally += 1;
        tallyEl.textContent = "POPS: " + tally;
        CARTRIDGE.send("score", { value: tally });
        return true;
      }
    }
    return false;
  }

  function clearTable() {
    pieces.length = 0;
    tally = 0;
    tallyEl.textContent = "POPS: 0";
    CARTRIDGE.send("score", { value: 0 });
    spawnBatch(10);
    draw();
  }

  function backToTitle() {
    running = false;
    clearTable();
  }

  // ---- Drawing ----
  function drawBackground() {
    ctx.fillStyle = PAPER;
    ctx.fillRect(0, 0, W, H);
  }

  function drawHalftoneShade(cx, cy, r, color) {
    // subtle halftone dots to fake shading on bubble edge
    ctx.save();
    ctx.globalAlpha = 0.35;
    ctx.fillStyle = color;
    const dotCount = 10;
    for (let i = 0; i < dotCount; i++) {
      const ang = (i / dotCount) * Math.PI * 2;
      const dr = r * 0.72;
      const dx = cx + Math.cos(ang) * dr;
      const dy = cy + Math.sin(ang) * dr;
      const rad = Math.max(1, r * 0.06);
      ctx.beginPath();
      ctx.arc(dx, dy, rad, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.restore();
  }

  function drawBubble(p) {
    if (p.popped) {
      // pop burst animation: expanding ring fragments
      const t = p.popT / 0.28;
      const alpha = Math.max(0, 1 - t);
      ctx.save();
      ctx.globalAlpha = alpha;
      ctx.strokeStyle = p.color === INK1 ? INK2 : INK1;
      ctx.lineWidth = 3;
      const spokes = 8;
      const dist = p.r * (0.6 + t * 0.9);
      for (let i = 0; i < spokes; i++) {
        const ang = (i / spokes) * Math.PI * 2;
        const x1 = p.x + Math.cos(ang) * p.r * 0.3;
        const y1 = p.y + Math.sin(ang) * p.r * 0.3;
        const x2 = p.x + Math.cos(ang) * dist;
        const y2 = p.y + Math.sin(ang) * dist;
        ctx.beginPath();
        ctx.moveTo(x1, y1);
        ctx.lineTo(x2, y2);
        ctx.stroke();
      }
      ctx.restore();
      return;
    }

    // misregistration offset layer (second ink offset by 2px)
    const otherColor = p.color === INK1 ? INK2 : INK1;

    ctx.save();
    ctx.globalAlpha = 0.9;
    ctx.fillStyle = otherColor;
    ctx.beginPath();
    ctx.arc(p.x + 2, p.y + 1.5, p.r, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();

    ctx.save();
    ctx.globalAlpha = 0.92;
    ctx.fillStyle = p.color;
    ctx.beginPath();
    ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();

    drawHalftoneShade(p.x, p.y, p.r, otherColor);

    // outline in overlap ink
    ctx.save();
    ctx.strokeStyle = OVERLAP;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
    ctx.stroke();
    ctx.restore();

    // highlight dot
    ctx.save();
    ctx.fillStyle = PAPER;
    ctx.globalAlpha = 0.85;
    ctx.beginPath();
    ctx.arc(p.x - p.r * 0.35, p.y - p.r * 0.35, p.r * 0.18, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }

  function drawGrain() {
    if (!grainTile) return;
    ctx.save();
    ctx.globalAlpha = 0.08;
    const pattern = ctx.createPattern(grainTile, "repeat");
    ctx.fillStyle = pattern;
    ctx.fillRect(0, 0, W, H);
    ctx.restore();
  }

  function drawTitleHint() {
    hintPulse += 0.05;
    const alpha = 0.55 + 0.45 * Math.sin(hintPulse);
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.fillStyle = OVERLAP;
    ctx.font = "bold " + Math.min(38, W * 0.08) + "px 'Arial Narrow', Arial, sans-serif";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText("TAP TO BEGIN", W / 2, H / 2);
    ctx.restore();

    ctx.save();
    ctx.fillStyle = INK1;
    ctx.font = "bold " + Math.min(26, W * 0.06) + "px 'Arial Narrow', Arial, sans-serif";
    ctx.textAlign = "center";
    ctx.fillText("POP THE BUBBLES", W / 2, H / 2 - 50);
    ctx.restore();
  }

  function draw() {
    drawBackground();
    for (const p of pieces) drawBubble(p);
    if (!running) drawTitleHint();
    drawGrain();
  }

  // ---- Loop ----
  let lastTime = performance.now();
  function frame(now) {
    const dt = Math.min(0.05, (now - lastTime) / 1000);
    lastTime = now;
    if (!paused && running) {
      settle(pieces, dt);
    }
    draw();
    requestAnimationFrame(frame);
  }

  // ---- Input ----
  canvas.style.touchAction = "none";
  canvas.addEventListener("pointerdown", (event) => {
    event.preventDefault();
    if (paused) return;
    const rect = canvas.getBoundingClientRect();
    const x = event.clientX - rect.left;
    const y = event.clientY - rect.top;
    if (!running) {
      running = true;
      CARTRIDGE.send("start");
      return;
    }
    popAt(x, y);
  });

  clearBtn.addEventListener("click", (e) => {
    e.stopPropagation();
    clearTable();
  });
  clearBtn.addEventListener("pointerdown", (e) => {
    e.stopPropagation();
  });

  // ---- Host bridge commands ----
  window.addEventListener("message", (event) => {
    const data = event.data;
    if (!data || data.source !== "cartridge-host") return;
    if (data.type === "pause") paused = true;
    if (data.type === "resume") paused = false;
    if (data.type === "reset") backToTitle();
  });

  // ---- Boot ----
  resize();
  spawnBatch(10);
  draw();
  CARTRIDGE.send("boot", { title: "Pop the Bubbles", gameType: "toy-box", lang: "en" });
  requestAnimationFrame(frame);
})();
</script>
</body>
</html>
"}}

